def spec = new JsonSlurper().parseText(CASES_JSON)
int passed = 0, failed = 0
List failures = []
List lines = []

for (sc in spec.scenarios) {
    Map ctx = new LinkedHashMap(spec.fixture)
    ctx.assignments = sc.assignments
    Map got = CreditPass.run(sc.transactions, ctx)
    Map st = got.stats
    List problems = []

    def want = sc.expect
    if (want.credits   != null && st.credits   != want.credits)   problems << ("credits "   + st.credits   + " != " + want.credits)
    if (want.matched   != null && st.matched   != want.matched)   problems << ("matched "   + st.matched   + " != " + want.matched)
    if (want.rolledUp  != null && st.rolledUp  != want.rolledUp)  problems << ("rolledUp "  + st.rolledUp  + " != " + want.rolledUp)
    if (want.unmatched != null && st.unmatched != want.unmatched) problems << ("unmatched " + st.unmatched + " != " + want.unmatched)
    if (want.exceptions != null) {
        List codes = got.exceptions.collect { it.code }.sort()
        List wantCodes = new ArrayList(want.exceptions).sort()
        if (codes != wantCodes) problems << ("exceptions " + codes + " != " + wantCodes)
    }
    if (want.creditTypes != null) {
        List types = got.credits.collect { it.creditTypeId }.sort()
        List wantTypes = new ArrayList(want.creditTypes).sort()
        if (types != wantTypes) problems << ("creditTypes " + types + " != " + wantTypes)
    }
    if (want.amounts != null) {
        List amts = got.credits.collect { it.amount.stripTrailingZeros().toPlainString() }.sort()
        List wantAmts = new ArrayList(want.amounts).sort()
        if (amts != wantAmts) problems << ("amounts " + amts + " != " + wantAmts)
    }

    if (problems.isEmpty()) { passed++; lines << ("ok   " + sc.name).toString() }
    else { failed++; lines << ("FAIL " + sc.name).toString(); failures << (sc.name + " | " + problems.join("; ")).toString() }
}

return [total: spec.scenarios.size(), passed: passed, failed: failed, failures: failures, lines: lines]
